// #region Tab View Context
export interface TabItemProps {
	/** The name of the trigger which activates this tab. Because it is used for triggers and querries, the name is not reactive and should not be changed after creation. */
	name: string;

	/** The title factory. This will appear as an item in the Tab.TabList and Tab.Title components. */
	title: Accessor<JSXElement>;

	/** The body factory. This will appear in the Tab.TabOutput when this tab is selected. */
	body: Accessor<JSXElement>;

	/** Is this tab disabled? Default: false */
	disabled?: boolean;

	/** Gets a reference of the component. For more info see {@link https://docs.solidjs.com/concepts/refs Refs}  */
	ref?: PropsRef<HTMLDivElement>;
}

export class TabContextProvider implements TriggerHost {
	private _active: Accessor<TabItemProps | undefined>;
	private _setActive: Setter<TabItemProps | undefined>;
	private _tabs: Accessor<TabItemProps[]>;
	private _mutateTabs: Mutator<TabItemProps[]>;
	private _isActive: (key: string) => boolean;
	private defaultTab: string | undefined;

	public get active() {
		return this._active;
	}

	public get tabs() {
		return this._tabs;
	}

	public get isActive() {
		return this._isActive;
	}

	constructor() {
		const [active, setActive] = createSignal<TabItemProps>();
		this._active = active;
		this._setActive = setActive;

		const [tabs, mutateTabs] = createArraySignal<TabItemProps>();
		this._tabs = tabs;
		this._mutateTabs = mutateTabs;

		this._isActive = createSelector(() => this._active()?.name);
	}

	public onTrigger(name: string, type: TriggerType, _source: HTMLElement | undefined) {
		if (type == TriggerType.Activate) {
			this.activate(name);
		}
	}

	public register(tab: TabItemProps) {
		const foundTabIndex = this._tabs().findIndex((t) => t.name == tab.name);

		if (foundTabIndex >= 0) {
			this._mutateTabs((tabs) => (tabs[foundTabIndex] = tab));
		} else {
			this._mutateTabs((tabs) => tabs.push(tab));
		}

		if (!this._active() && (!this.defaultTab || tab.name == this.defaultTab)) {
			this._setActive(tab);
		}
	}

	public unregister(tabName: string) {
		const foundTabIndex = this._tabs().findIndex((t) => t.name == tabName);
		if (foundTabIndex >= 0) {
			this._mutateTabs((tabs) => tabs.splice(foundTabIndex, 1));
		}
	}

	public activate(tabName: string) {
		const tab = this._tabs().find((t) => t.name == tabName);
		if (tab && !tab.disabled) {
			this._setActive(tab);
			return this._tabs().length > 1;
		}
		return false;
	}

	public activateNext() {
		const active = this._active();
		const tabs = this._tabs();

		if (active) {
			const activeIndex = tabs.indexOf(active) + 1;

			for (let i = 0; i < tabs.length; i++) {
				const nextTab = tabs[(activeIndex + i) % tabs.length];
				if (!nextTab.disabled) {
					this._setActive(nextTab);
					return tabs.length > 1;
				}
			}
		}
		return false;
	}

	public activatePrevious() {
		const active = this._active();
		const tabs = this._tabs();
		if (active) {
			const activeIndex = tabs.indexOf(active) - 1;

			for (let i = 0; i < tabs.length; i++) {
				const prevTab = tabs[(activeIndex - i + tabs.length) % tabs.length];
				if (!prevTab.disabled) {
					this._setActive(prevTab);
					return tabs.length > 1;
				}
			}
		}
		return false;
	}

	public setDefaultTab(tabName: string) {
		this.activate(tabName);
		this.defaultTab = tabName;
	}

	public getActiveTabIndex() {
		return this._tabs().findIndex((tab) => this._isActive(tab.name)) + 1;
	}
}

export const TabContext = createContext<TabContextProvider>();

export function useTabContext() {
	const context = useContext(TabContext);

	if (!context) {
		throw new Error("useTabContext - Unable to get tab context");
	}

	return context;
}
// #endregion

// #region Tab
export interface TabProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/** The tab which should be shown on start. Default: undefined (will use first tab) */
	defaultTab?: string;
	/** Event which triggers when the tab changes */
	onTabChanged?: (tab: TabItemProps | undefined) => void;
	/** For controlling the tabs outside the context */
	activeTab?: Accessor<string>;
}

const TabComponent: ParentComponent<TabProps> = (props) => {
	const contextProvider = new TabContextProvider();

	createEffect(() => {
		props.onTabChanged?.(contextProvider.active());
	});

	createEffect(() => {
		if (props.defaultTab) {
			contextProvider.setDefaultTab(props.defaultTab);
		}
	});

	createEffect(() => {
		const activeTab = props.activeTab?.();
		if (activeTab) {
			contextProvider.activate(activeTab);
		}
	});

	return (
		<div
			{...props}
			ref={props.ref}
			class={props.class ?? "flex flex-row"}
			data-name="Tab"
		>
			<TabContext.Provider value={contextProvider}>{props.children}</TabContext.Provider>
		</div>
	);
};
// #endregion

// #region Tab Output
interface TabOutputProps {
	/** Gets a reference of the component. For more info see {@link https://docs.solidjs.com/concepts/refs Refs}  */
	ref?: PropsRef<HTMLElement>;
}
const TabOutputComponent: Component = (props: TabOutputProps) => {
	const tabContext = useContext(TabContext);
	return (
		<Dynamic
			ref={props.ref}
			component={tabContext?.active()?.body}
		/>
	);
};
// #endregion

// #region Tab Title
const TabTitleComponent: Component = () => {
	const tabContext = useContext(TabContext);
	return <Dynamic component={tabContext?.active()?.title} />;
};
// #endregion

// #region Tab Item
// This component is used to organize the tab title and tab body in a single place
const TabItemComponent: Component<TabItemProps> = (props) => {
	const tabContext = useContext(TabContext);
	onMount(() => tabContext?.register(props));
	onCleanup(() => tabContext?.unregister(props.name));

	// This component doesnt directly generate HTML Elements in place, instead it defines the header and body which get loaded elsewhere
	return null;
};
// #endregion

// #region Tab List (Default)
interface TabListItemProps {
	/** Is this tab list item selected? */
	selected: boolean;
	/** Is this tab list item disabled? Default: false */
	disabled: boolean;
	/** Gets a reference of the component. For more info see {@link https://docs.solidjs.com/concepts/refs Refs}  */
	ref?: PropsRef<HTMLDivElement>;
	/** Class info to apply to the tab item's name  */
	titleClass?: string;
}

const TabListItem: ParentComponent<TabListItemProps> = (props) => {
	return (
		<Activatable
			ref={props.ref}
			class={`relative flex items-center justify-center font-fit-shrink text-center flex-1 ${props.titleClass ?? ""}`}
			classList={{
				"text-secondary": props.selected && !props.disabled,
				"text-accent-1": !props.selected && !props.disabled,
				"text-accent-5": props.disabled,
				"cursor-pointer": !props.disabled,
			}}
			disabled={props.disabled}
			disableFocus={true}
			name="TabListItem"
		>
			{props.children}
		</Activatable>
	);
};

export interface TabListBaseProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/** The hotkey which cycles to the next tab. Default: nav-previous */
	previousHotkey?: string;
	/** The hotkey which cycles to the next tab. Default: nav-next */
	nextHotkey?: string;
	/** Is this tab list disabled? Default: false */
	disabled?: boolean;
}

export interface TabListProps extends TabListBaseProps {
	/** Should the tab list show controller nav helpers when using a controller? Default: true */
	showNavHelp?: boolean;
	showPages?: boolean;
	/** Class info to apply to the tab item's name  */
	titleClass?: string;
}

export interface TabListRadioProps extends TabListProps {
	size?: RadioButtonSize;
}

const TabListComponent: Component<TabListProps> = (props) => {
	const tabContext = useContext(TabContext);
	const focusContext = useContext(FocusContext);

	const [root, setRoot] = createPropsRefSignal(() => props.ref);
	const layoutComplete = createLayoutComplete();

	let selectionIndicator: HTMLDivElement | undefined;

	const showNavHelp = createMemo(() => props.showNavHelp ?? true);
	const nextHotkey = createMemo(() => props.nextHotkey ?? "nav-next");
	const prevHotkey = createMemo(() => props.previousHotkey ?? "nav-previous");

	createEffect(() => {
		const resolvedRoot = root();
		if (!resolvedRoot || !selectionIndicator || !layoutComplete()) {
			return;
		}

		const selectedTab = tabContext?.active()?.ref;
		if (!selectedTab) {
			return;
		}

		const rootRect = resolvedRoot.getBoundingClientRect();
		const tabRect = (selectedTab as HTMLDivElement).getBoundingClientRect();

		selectionIndicator.style.left = `${tabRect.left - rootRect.left}px`;
		selectionIndicator.style.width = `${tabRect.width}px`;
	});

	const audioTrigger = useAudio("TabListItem");

	const navigateNextTab = () => {
		if (tabContext?.activateNext()) {
			focusContext.focusCurrent();
			audioTrigger("tab-nav-next");
		}
	};

	const navigatePreviousTab = () => {
		if (tabContext?.activatePrevious()) {
			focusContext.focusCurrent();
			audioTrigger("tab-nav-previous");
		}
	};

	return (
		<div
			ref={setRoot}
			{...props}
			class={`flex flex-row items-stretch justify-stretch relative uppercase font-title text-base text-accent-2 tracking-150 min-h-16 px-4 ${
				props.class ?? ""
			}`}
			data-name="TabList"
		>
			<div class="absolute inset-0 img-tab-bar" />
			<div class="absolute -left-1 img-tab-end-cap pointer-events-none left-border" />
			<div class="absolute -right-1 rotate-y-180 img-tab-end-cap pointer-events-none right-border" />
			<Show when={showNavHelp()}>
				<Activatable
					class="absolute top-4 -left-10"
					disableFocus={true}
					disabled={props.disabled}
					hotkeyAction={prevHotkey()}
					onActivate={navigatePreviousTab}
				>
					<NavHelp />
				</Activatable>
			</Show>
			<For each={tabContext?.tabs()}>
				{(tab) => (
					<Tab.Trigger name={tab.name}>
						<TabListItem
							ref={tab.ref as Setter<HTMLDivElement>}
							disabled={(props.disabled || tab.disabled) ?? false}
							selected={tabContext?.isActive(tab.name) || false}
							titleClass={props.titleClass}
						>
							{tab.title()}
						</TabListItem>
					</Tab.Trigger>
				)}
			</For>
			<Show when={showNavHelp()}>
				<Activatable
					class="absolute top-4 -right-10"
					disableFocus={true}
					disabled={props.disabled}
					hotkeyAction={nextHotkey()}
					onActivate={navigateNextTab}
				>
					<NavHelp />
				</Activatable>
			</Show>
			<div
				ref={selectionIndicator}
				class="absolute bottom-0 left-0 img-tab-selection-indicator bg-no-repeat bg-center min-h-6 bg-contain transition-left duration-150"
			/>
		</div>
	);
};
// #endregion

// #region Tab List Pips
const TabListPipsComponent: Component<TabListRadioProps> = (props) => {
	const tabContext = useContext(TabContext);
	const focusContext = useContext(FocusContext);

	const showNavHelp = createMemo(() => props.showNavHelp ?? true);
	const nextHotkey = createMemo(() => props.nextHotkey ?? "nav-next");
	const prevHotkey = createMemo(() => props.previousHotkey ?? "nav-previous");

	const audioTrigger = useAudio("RadioItem");

	const navigateNextTab = () => {
		if (tabContext?.activateNext()) {
			focusContext.focusCurrent();
			audioTrigger("tab-nav-next");
		}
	};

	const navigatePreviousTab = () => {
		if (tabContext?.activatePrevious()) {
			focusContext.focusCurrent();
			audioTrigger("tab-nav-previous");
		}
	};

	return (
		<div
			{...props}
			class={`flex flex-row items-center justify-center ${props.class ?? ""}`}
			data-name="TabListPips"
		>
			<Show when={tabContext && tabContext?.tabs().length > 1}>
				<ArrowButton
					class={`mr-1 -my-1`}
					hideForController={true}
					disableFocus={true}
					disabled={props.disabled}
					onActivate={navigatePreviousTab}
				/>

				<Show when={showNavHelp()}>
					<Activatable
						class="mr-1"
						disableFocus={true}
						disabled={props.disabled}
						hotkeyAction={prevHotkey()}
						onActivate={navigatePreviousTab}
					>
						<NavHelp class="size-10" />
					</Activatable>
				</Show>
			</Show>
			<Show
				when={!props.showPages}
				fallback={
					<div
						class="text-secondary-1"
						role="menuitem"
					>
						{tabContext && (
							<L10n.Compose
								text="LOC_ADVISOR_COUNCIL_PAGE"
								args={[tabContext?.getActiveTabIndex(), tabContext?.tabs().length]}
							/>
						)}
					</div>
				}
			>
				<For each={tabContext?.tabs()}>
					{(tab) => (
						<Tab.Trigger name={tab.name}>
							<RadioButton
								disableFocus={true}
								size={props.size}
								isChecked={tabContext?.isActive(tab.name) || false}
								class="m-0\.5"
							/>
						</Tab.Trigger>
					)}
				</For>
			</Show>
			<Show when={tabContext && tabContext?.tabs().length > 1}>
				<Show when={showNavHelp()}>
					<Activatable
						class="ml-1"
						disableFocus={true}
						disabled={props.disabled}
						hotkeyAction={nextHotkey()}
						onActivate={navigateNextTab}
					>
						<NavHelp class="size-10" />
					</Activatable>
				</Show>
				<ArrowButton
					class={`ml-1 -my-1`}
					hideForController={true}
					right={true}
					disableFocus={true}
					disabled={props.disabled}
					onActivate={navigateNextTab}
				/>
			</Show>
		</div>
	);
};
// #endregion

// #region Exports
export type TabComponents = ParentComponent<TabProps> & {
	/**
	 * A tab item to be displayed in a {@link Tab} component.
	 * ```tsx
	 *   <Tab.Item Title={() => "Tab Title"} Body={() => "Tab Contents"} />
	 * ```
	 * Default implementation: {@link TabItemComponent}
	 * @param {TabItemProps} props See {@link TabItemProps} for a full list of properties
	 *
	 * Commonly Used Properties:
	 * @param {string} props.name The name of the trigger which activates this tab. Because it is used for triggers and querries, the name is not reactive and should not be changed after creation.
	 * @param {string} props.title The title factory. This will appear as an item in the {@link Tab.TabList} and {@link Tab.Title} components.
	 * @param {string} props.body The body factory. This will appear in the {@link Tab.Output} when this tab is selected.
	 * @see {@link Tab} for more information about tabs and each of its sub-components.
	 */
	Item: Component<TabItemProps>;
	/**
	 * The tab output component.
	 * Displays the body of the currently selected {@link Tab.Item}
	 * ```tsx
	 *   <Tab.Output />
	 * ```
	 * Default implementation: {@link TabOutputComponent}
	 * @param {TabOutputProps} props See {@link TabOutputProps} for a full list of properties
	 * @see {@link Tab} for more information about tabs and each of its sub-components.
	 */
	Output: Component;
	/**
	 * The tab title component.
	 * Displays the title of the currently selected {@link Tab.Item}
	 * ```tsx
	 *   <Tab.Header />
	 * ```
	 * Default implementation: {@link TabTitleComponent}
	 * @see {@link Tab} for more information about tabs and each of its sub-components.
	 */
	Title: Component;
	/**
	 * The tab trigger component.
	 * Can be used to trigger tab changes from components within the {@link Tab}.
	 * Also useful for implementing custom derivations of {@link Tab.TabList}.
	 * ```tsx
	 * <Tab>
	 *   <Tab.TabList />
	 *   <Tab.Output />
	 *   <Tab.Item name="tab1" title={() => "Tab 1"} body={() => "Tab 1 Contents"} />
	 *   <Tab.Item name="tab2" title={() => "Tab 2"} body={() => (
	 *     <Tab.Trigger name="tab1">
	 *       <Button>Switch to Tab 1</Button>
	 *     </Tab.Trigger>
	 *    )}/>
	 * </Tab>
	 * ```
	 * @param {TriggerProps} props See {@link TriggerProps} for a full list of properties
	 *
	 * Commonly Used Properties:
	 * @param {string} props.name The name of the tab to activate, changing the selected tab.
	 * @see {@link Tab} for more information about tabs and each of its sub-components.
	 */
	Trigger: ParentComponent<TriggerProps>;
	/**
	 * The defualt tab list.
	 * Displays a list of a available tabs with a bar under the selected tab, to be used as a header.
	 * ```tsx
	 * <Tab.TabList />
	 * ```
	 * Default implementation: {@link TabListComponent}
	 * @param {TabListProps} props See {@link TabListProps} for a full list of properties
	 * @see {@link Tab} for more information about tabs and each of its sub-components.
	 */
	TabList: Component<TabListProps>;
	/**
	 * A pip based tab list.
	 * Displays a list of a available tabs as pips.
	 * ```tsx
	 * <Tab.TabListPips />
	 * ```
	 * Default implementation: {@link TabListPips}
	 * @param {TabListRadioProps} props See {@link TabListRadioProps} for a full list of properties
	 * @see {@link Tab} for more information about tabs and each of its sub-components.
	 */
	TabListPips: Component<TabListRadioProps>;
};

/**
 * A freeform tab component.
 * Allows the display of multiple screens on the same page using tabbed navigation to switch between them.
 * This component acts as the coordinator for the other tab component pieces and does not have any display logic on its own.
 * Add a Tab.TabList as a child to display the list of tabs, a Tab.Output to show the contents of the currently selected tab, and a Tab.Item for each tab you want to display.
 * ```tsx
 * <Tab>
 *   <Tab.TabList />
 *   <Tab.Output />
 *   <Tab.Item Title={() => "Tab 1"} Body={() => "Tab 1 Contents"} />
 *   <Tab.Item Title={() => "Tab 2"} Body={() => "Tab 2 Contents"} />
 * </Tab>
 * ```
 * Default implementation: {@link TabComponent}
 * @param {TabProps} props See {@link TabProps} for a full list of properties
 * @see {@link Tab.Item}, {@link Tab.Output}, {@link Tab.Title}, {@link Tab.Trigger}, {@link Tab.TabList}, {@link Tab.TabListPips} for more information about each of the sub-components.
 */
export const Tab = ComponentRegistry.register("Tab", TabComponent) as ParentComponent<TabProps> as TabComponents;
Tab.Item = ComponentRegistry.register("Tab.Item", TabItemComponent);
Tab.Output = ComponentRegistry.register("Tab.Output", TabOutputComponent);
Tab.Title = ComponentRegistry.register("Tab.Title", TabTitleComponent);
Tab.Trigger = ComponentRegistry.register("Tab.Trigger", createTrigger(TabContext));
Tab.TabList = ComponentRegistry.register({
	name: "Tab.TabList",
	createInstance: TabListComponent,
	images: ["blp:base_tabbar-selector", "blp:base_tabbar-bg", "blp:base_tabbar-endcap"],
});
Tab.TabListPips = ComponentRegistry.register("Tab.TabListPips", TabListPipsComponent);
// #endregion
